import { Button, ListGroup, ListGroupItem } from 'react-bootstrap';

import PohAva from '@ui-kit/Ava';

import { ICheckAnotherLoginVarsDTO } from '../../../@types/auth.types';

interface ISelectLoginVariantProps {
  vars: ICheckAnotherLoginVarsDTO[];
  provider: string;
  onVariantClick: (v: ICheckAnotherLoginVarsDTO) => void;
  onNewClick: () => void;
}

function SelectLoginVariant({
  vars,
  provider,
  onVariantClick,
  onNewClick,
}: ISelectLoginVariantProps) {
  return (
    <div>
      <p style={{ textAlign: 'center' }}>
        <PohAva src={vars[0].photo_50} width={50} alt={`${vars[0].name} ${vars[0].surname}`} />
        <br />
        <strong>{`${vars[0].name}\u00a0${vars[0].surname}`}</strong>
      </p>
      <p>А мы тебя узнали. </p>
      <p>
        Мы можем привязать эту учетную запись <b>{provider}</b> к личному кабинету.
      </p>
      <p>Для этого нужно подтвердить вход одним из ранее используемых способов:</p>
      <ListGroup>
        {vars.map((item) => (
          <ListGroupItem key={item.id_user}>
            <Button
              className="float-end"
              onClick={() => {
                onVariantClick(item);
              }}
            >
              Войти
            </Button>
            {item.provider_name || item.provider || item.network}
          </ListGroupItem>
        ))}
      </ListGroup>
      <hr />
      <Button onClick={onNewClick}>Создать новую учетку</Button>
    </div>
  );
}

export default SelectLoginVariant;
