import { get, handleApiError, post } from '@helpers/httpClient';

import {
  IAddLoginVariantCriteria,
  IAddLoginVariantDTO,
  IAuthProviderDTO,
  ICheckAnotherLoginVarsCriteria,
  ICheckAnotherLoginVarsDTO,
  IExternalSystem,
  IRegisterOverProviderCriteria,
  IRegisterOverProviderDTO,
} from '../@types/auth.types';

export const getProvidersList = () =>
  get('/ajax/auth/providers_list.php').then<IAuthProviderDTO[]>(handleApiError);

export const registerOverProvider = (data: IRegisterOverProviderCriteria) => {
  return post('/ajax/auth/register_over_provider.php', data).then<IRegisterOverProviderDTO>(
    handleApiError,
  );
};

export const getAnotherLoginVariants = (data: ICheckAnotherLoginVarsCriteria) => {
  return get('/ajax/auth/check_another_login_vars.php', data).then<ICheckAnotherLoginVarsDTO[]>(
    handleApiError,
  );
};

export const addLoginVariant = (data: IAddLoginVariantCriteria) => {
  return post('/ajax/auth/add_login_variant.php', data).then<IAddLoginVariantDTO>(handleApiError);
};

export const getExternalApp = (clientId: string) => {
  return get('/ajax/externalApp/get.php', { id: clientId }).then<IExternalSystem>(handleApiError);
};
