import { allowDomains } from '@helpers/domain.helper';
import PohButton from '@ui-kit/Button';
import { showModal } from '@ui-kit/Modal';

import ConfirmAddVariant from './ConfirmAddVariant';
import SelectLoginVariant from './SelectLoginVariant';
import { IAuthContext } from '../../../../contexts/AuthContext';
import {
  addLoginVariant,
  getAnotherLoginVariants,
  registerOverProvider,
} from '../../@services/auth.services';
import {
  IAddLoginVariantCriteria,
  ICheckAnotherLoginVarsDTO,
  IRegisterOverProviderCriteria,
} from '../../@types/auth.types';

let win: WindowProxy | null = null;
let globalAuthCallback: IAuthContext['onLogin'] = () => {};
let afterLoginCb: IAuthContext['onLogin'] = () => {};

function registerAndLogin({ data }: { data: IRegisterOverProviderCriteria }, callback: () => void) {
  registerOverProvider(data).then((res) => {
    globalAuthCallback?.(
      {
        id: res.user,
        hash: res.token,
      },
      () => {
        callback();
        afterLoginCb?.({
          id: res.user,
          hash: res.token,
        });
      },
    );
  });
}

function onDataFromChildHandler(event: MessageEvent) {
  if (!allowDomains.includes(new URL(event.origin).host)) {
    return;
  }

  const { result, new: isNew, uid, data } = event.data;

  const onOkHandler = () => {
    afterLoginCb?.({
      id: uid,
      hash: data.token,
    });
  };

  if (result && !isNew && uid) {
    globalAuthCallback &&
      globalAuthCallback(
        {
          id: uid,
          hash: data.token,
        },
        afterLoginCb,
      );
  } else if (result && isNew) {
    document.cookie = `hash=${data.token}; expires=${new Date(Date.now() + 86400000).toUTCString()}`;
    getAnotherLoginVariants({
      token: data.token,
      socialId: data.socialId,
      email: data.email,
    }).then((vars) => {
      if (!vars.length) {
        registerAndLogin(event.data, () => {});
        return;
      }

      showModal({
        title: `Привет, ${vars[0].name}`,
        width: 320,
        children: (clean) => (
          <>
            <SelectLoginVariant
              onNewClick={() => registerAndLogin(event.data, clean)}
              onVariantClick={(item) => {
                loginAndJoin(item, event.data);
                clean();
              }}
              provider={data.provider}
              vars={vars}
            />
            <footer className="mt-3 text-end">
              <PohButton onClick={onOkHandler}>ok</PohButton>
            </footer>
          </>
        ),
      });
    });
  }

  window.removeEventListener('message', onDataFromChildHandler, false);
  win && win.close();
}

const onDataLoginAndJoinHandler =
  (saveData: { data: IRegisterOverProviderCriteria }) => (event: MessageEvent) => {
    if (!allowDomains.includes(new URL(event.origin).host)) {
      return;
    }
    const { result, new: isNew, uid, data } = event.data;

    if (result && !isNew && uid) {
      globalAuthCallback &&
        globalAuthCallback(
          {
            id: uid,
            hash: data.token,
          },
          () => {
            const {
              data: { avatar, birthday, email, name, provider, sex, socialId, socialPage },
            } = saveData;

            const dataForSave: IAddLoginVariantCriteria = {
              avatar,
              birthday,
              email,
              name,
              provider,
              sex,
              socialId,
              socialPage,
              updateEmail: 'true',
              updateAva: 'true',
            };

            const onChangeEmailUp = (checked: boolean) => {
              dataForSave.updateEmail = checked ? 'true' : 'false';
            };

            const onChangeAvaUp = (checked: boolean) => {
              dataForSave.updateAva = checked ? 'true' : 'false';
            };

            showModal({
              title: 'Отлично',
              children: () => (
                <>
                  <ConfirmAddVariant
                    avatar={avatar}
                    provider={provider}
                    email={email}
                    onChangeAvaUp={onChangeAvaUp}
                    onChangeEmailUp={onChangeEmailUp}
                    socialPage={socialPage}
                    name={name}
                  />
                  <footer className="mt-3 text-end">
                    <PohButton
                      onClick={() => {
                        addLoginVariant(dataForSave).then(() => {
                          afterLoginCb?.({
                            id: uid,
                            hash: data.token,
                          });
                        });
                      }}
                    >
                      Сохранить вход через {provider}
                    </PohButton>
                  </footer>
                </>
              ),
            });
          },
        );
    }

    window.removeEventListener('message', onDataLoginAndJoinHandler(saveData), false);
    win && win.close();
  };

const onDataFromLoginVariantHandler =
  (resolve: (a: IAddLoginVariantCriteria) => void, reject: () => void) => (event: MessageEvent) => {
    if (!allowDomains.includes(new URL(event.origin).host)) {
      return;
    }
    const {
      data: { avatar, birthday, email, name, provider, sex, socialId, socialPage },
    } = event.data;

    const dataForSave: IAddLoginVariantCriteria = {
      avatar,
      birthday,
      email,
      name,
      provider,
      sex,
      socialId,
      socialPage,
      updateEmail: 'true',
      updateAva: 'true',
    };

    const onChangeEmailUp = (checked: boolean) => {
      dataForSave.updateEmail = checked ? 'true' : 'false';
    };

    const onChangeAvaUp = (checked: boolean) => {
      dataForSave.updateAva = checked ? 'true' : 'false';
    };

    showModal({
      title: 'Добавление варианта входа',
      children: (clean) => (
        <>
          <ConfirmAddVariant
            avatar={avatar}
            provider={provider}
            email={email}
            name={name}
            socialPage={socialPage}
            onChangeAvaUp={onChangeAvaUp}
            onChangeEmailUp={onChangeEmailUp}
          />
          <footer className="mt-3 text-end">
            <PohButton
              onClick={() => {
                addLoginVariant(dataForSave)
                  .then((res) => {
                    clean();
                    resolve({ ...res, ...dataForSave });
                  })
                  .catch(() => {
                    clean();
                    reject();
                  });
              }}
            >
              Сохранить вход через ${provider}
            </PohButton>
          </footer>
        </>
      ),
    });

    window.removeEventListener('message', onDataFromLoginVariantHandler(resolve, reject), false);
    win && win.close();
  };

function loginAndJoin(
  { url }: ICheckAnotherLoginVarsDTO,
  data: { data: IRegisterOverProviderCriteria },
) {
  window.removeEventListener('message', onDataFromChildHandler, false);
  window.addEventListener('message', onDataLoginAndJoinHandler(data), false);
  win = window.open(url);
  win && win.focus();
}

export function addSocialAuthAsync({ url }: ICheckAnotherLoginVarsDTO) {
  return new Promise((res, rej) => {
    window.addEventListener('message', onDataFromLoginVariantHandler(res, rej), false);
    win = window.open(url);
    win && win.focus();
  });
}

export function socialAuthGo(
  uri: string,
  onLogin: typeof globalAuthCallback,
  afterLogin: typeof afterLoginCb,
) {
  window.addEventListener('message', onDataFromChildHandler, false);
  win = window.open(uri);
  win && win.focus();
  globalAuthCallback = onLogin;
  afterLoginCb = afterLogin;
}

export default {
  socialAuthGo,
};
